'use strict';
const $=id=>document.getElementById(id),KEY='qingri.v1',names=['早餐','午餐','晚餐'],icons=['☀','☼','☾'],english=['BREAKFAST','LUNCH','DINNER'];
let storageOK=true,state={goal:1200,days:{}},selected=localDate(),activeMeal=0,editId=null;
function localDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function validFood(f){return f&&typeof f.id==='string'&&typeof f.name==='string'&&['grams','kcal','carbs','protein','fat'].every(k=>Number.isFinite(f[k])&&f[k]>=0);}
try{const raw=localStorage.getItem(KEY);if(raw){const p=JSON.parse(raw);if(!p||!Number.isFinite(p.goal)||p.goal<=0||p.goal>10000||!p.days||typeof p.days!=='object')throw Error('invalid');Object.values(p.days).forEach(d=>{if(!d||!Array.isArray(d.meals)||d.meals.length!==3||!d.meals.every(m=>Array.isArray(m)&&m.every(validFood))||!Number.isFinite(d.water)||d.water<0)throw Error('invalid');});state=p;}}catch{storageOK=false;}
function day(){return state.days[selected]||{meals:[[],[],[]],water:0,sleep:false,read:false};}
function mutate(fn){const d=day();fn(d);state.days[selected]=d;persist();render();}
function persist(){try{if(!storageOK){$('save-status').textContent='无法读取本地数据 · 当前更改尚未保存';return;}localStorage.setItem(KEY,JSON.stringify(state));$('save-status').textContent='已保存在此浏览器 · 无需注册';}catch{$('save-status').textContent='保存失败，请检查浏览器存储空间 · 当前记录仅暂存';}}
function totals(d=day()){return d.meals.flat().reduce((t,f)=>{for(const k of Object.keys(t))t[k]+=f[k];return t;},{kcal:0,carbs:0,protein:0,fat:0});}
function advice(d,t){const left=Math.max(0,state.goal-t.kcal),next=d.meals.findIndex(m=>m.length===0),count=d.meals.filter(m=>!m.length).length;const targets=[state.goal*.45/4,state.goal*.25/4,state.goal*.3/9],deficits=targets.map((v,i)=>Math.max(0,v-t[['carbs','protein','fat'][i]]));const energy=deficits[0]*4+deficits[1]*4+deficits[2]*9;const mealEnergy=left/Math.max(1,count);const scale=energy>0?mealEnergy/energy:0;return {left,next,grams:deficits.map(v=>Math.round(v*scale)),mealEnergy};}
const n=v=>Math.round(v).toLocaleString('zh-CN');
function render(){const d=day(),t=totals(d),a=advice(d,t);$('date').value=selected;$('date').max=localDate();$('next').disabled=selected>=localDate();$('eaten').textContent=n(t.kcal);$('target').textContent=n(state.goal);$('remaining').textContent=n(Math.abs(state.goal-t.kcal));$('balance-label').textContent=t.kcal>state.goal?'超出目标':'剩余可摄入';$('ring').style.background=`conic-gradient(${t.kcal>state.goal?'#ce927c':'#849765'} ${Math.min(1,t.kcal/state.goal)*360}deg,#ecebdd 0)`;
$('macros').replaceChildren();[['碳水','carbs',.45/4,'#b3bd78'],['蛋白质','protein',.25/4,'#81978d'],['脂肪','fat',.3/9,'#d8ad94']].forEach(([name,k,ratio,color])=>{const el=document.createElement('div');el.className='macro';el.innerHTML=`<div class="macro-label"><b>${name}</b><span>${n(t[k])}${d.meals.flat().some(f=>f.missing?.includes(k))?'+':''} / ${n(state.goal*ratio)} g</span></div><div class="track"><i style="width:${Math.min(100,t[k]/(state.goal*ratio)*100)}%;background:${color}"></i></div>`;$('macros').append(el);});
$('meals').replaceChildren();d.meals.forEach((items,i)=>{const el=document.createElement('article');el.className='meal';el.innerHTML=`<div class="meal-header"><span class="meal-icon">${icons[i]}</span><div class="meal-info"><b>${names[i]}</b><small>${english[i]}</small></div><span class="meal-total">${items.length?n(items.reduce((s,f)=>s+f.kcal,0))+' kcal':'还未记录'}</span><button class="add-food" aria-label="添加${names[i]}">＋</button></div><div class="food-list"></div>`;el.querySelector('.add-food').onclick=()=>openFood(i);items.forEach(f=>{const row=document.createElement('div');row.className='food-row';const label=document.createElement('span');label.className='food-name';label.textContent=f.name;const amount=document.createElement('small');amount.textContent=`${f.portion||n(f.grams)+'g'} · ${n(f.kcal)} kcal`;const edit=document.createElement('button');edit.textContent='编辑';edit.setAttribute('aria-label',`编辑${f.name}`);edit.onclick=()=>openFood(i,f);const del=document.createElement('button');del.textContent='×';del.setAttribute('aria-label',`删除${f.name}`);del.onclick=()=>{if(confirm(`删除「${f.name}」？`))mutate(d=>d.meals[i]=d.meals[i].filter(v=>v.id!==f.id));};row.append(label,amount,edit,del);el.querySelector('.food-list').append(row);});$('meals').append(el);});
const incomplete=d.meals.flat().some(f=>f.missing?.length);
const mealCount=d.meals.filter(m=>m.length).length;$('meal-count').textContent=`${mealCount} / 3 餐已记录`;
$('advice-title').textContent=a.next<0?'今天的三餐，都记下了':`下一餐 · ${names[a.next]}`;$('advice-description').textContent=a.left<=0?'今日已达到设定热量。仍有饥饿感时，请正常进食，关注身体需要。':a.next<0?'三餐已记录。下面是当天剩余营养参考，无需为了数字强行补齐。':`还有 ${n(a.left)} kcal 规划空间，按 ${3-mealCount} 餐分配，这一餐约 ${n(a.mealEnergy)} kcal。`;
$('advice-macros').innerHTML=a.left>0?a.grams.map((g,i)=>`<div><strong>${g}<small>g</small></strong><span>${['碳水','蛋白质','脂肪'][i]}</span></div>`).join(''):'';
$('advice-note').textContent=a.left<=0?'不必跳餐或额外运动补偿。明天继续规律饮食就好。':a.next<0?'食物数值是估算，饱腹感、精力与恢复同样值得关注。':a.grams[1]>=20?'搭配参考：一份鱼肉、鸡胸或豆腐，加米饭 / 红薯与蔬菜；烹调油也记得计入。':'搭配参考：全谷物或薯类、适量蛋奶 / 豆制品与蔬菜，按上方克数灵活调整。';
if(incomplete){$('advice-macros').replaceChildren();$('advice-description').textContent='部分包装食品缺少完整营养素。热量已计入，下一餐的精确克数暂不估算。';$('advice-note').textContent='可以补充包装标签中的蛋白质、脂肪与碳水数据，再查看克数建议。';}
$('water').textContent=n(d.water);$('water-fill').style.width=Math.min(100,d.water/2000*100)+'%';$('water-minus').disabled=d.water===0;$('sleep').checked=!!d.sleep;$('read').checked=!!d.read;const done=Number(d.water>=2000)+Number(!!d.sleep)+Number(!!d.read);$('habit-count').textContent=`${done} / 3`;$('habit-footer').textContent=done===3?'今天的自己，被好好照顾了。':'慢慢来，每一小步都算数。';if(typeof renderTracker==='function')renderTracker();if(!storageOK)$('save-status').textContent='本地存储不可用或数据异常 · 新记录仅暂存';}
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());
$('settings').onclick=()=>{$('goal-input').value=state.goal;$('settings-dialog').showModal();};$('settings-form').onsubmit=e=>{e.preventDefault();state.goal=Number($('goal-input').value);persist();render();$('settings-dialog').close();};
$('water-plus').onclick=()=>mutate(d=>d.water+=250);$('water-minus').onclick=()=>mutate(d=>d.water=Math.max(0,d.water-250));['sleep','read'].forEach(k=>$(k).onchange=()=>mutate(d=>d[k]=$(k).checked));
$('date').onchange=()=>{if(/^\d{4}-\d{2}-\d{2}$/.test($('date').value)&&$('date').value<=localDate())selected=$('date').value;render();};function shift(amount){const d=new Date(selected+'T12:00:00');d.setDate(d.getDate()+amount);selected=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;render();}$('prev').onclick=()=>shift(-1);$('next').onclick=()=>shift(1);$('today').onclick=()=>{selected=localDate();render();};
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_daily_nutrition',description:'读取当前所选日期的饮食、营养汇总和习惯状态。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({date:selected,goal:state.goal,totals:totals(),habits:{water:day().water,sleep:!!day().sleep,read:!!day().read},advice:advice(day(),totals())})})).catch(()=>{});}catch{}}
